/**
 * Create Vendor intent type
 */
type NetsuiteCreateVendor = {
  /**
   * Record Type
   *
   */
  recordType?: string;

  /**
   * Company Name
   *
   */
  companyName: string;

  /**
   * Primary Subsidiary
   *
   */
  subsidiary?: string;

  /**
   * Email
   *
   * **Example**:
   * ```
   * primary@vendor.com
   * ```
   */
  email?: string;

  /**
   * Alternative Email
   *
   * **Example**:
   * ```
   * secondary@vendor.com
   * ```
   */
  altEmail?: string;

  /**
   * Default Tax Registration Number
   *
   */
  defaultTaxReg?: string;

  /**
   * Expense Account
   * Specify an account associated with this vendor.
   *
   */
  expenseAccount?: string;

  /**
   * Term
   * The ID of the payment term for this vendor.
   *
   */
  terms?: string;

  /**
   * Address Line 1
   *
   */
  addr1?: string;

  /**
   * Address Line 2
   *
   */
  addr2?: string;

  /**
   * City
   *
   */
  city?: string;

  /**
   * State
   * Use state or province.
   *
   */
  state?: string;

  /**
   * Zip
   * Use ZIP or postal code, if applicable.
   *
   */
  zip?: string;

  /**
   * Country
   * Accepts ISO-3166 country codes.
   *
   * **Example**:
   * ```
   * US
   * ```
   */
  country?: string;

  /**
   * Additional Fields
   * Specify additional fields to include on this vendor as JSON. For example, you may specify a different billing address here. See the docs (https://system.netsuite.com/help/helpcenter/en_US/APIs/REST_API_Browser/record/v1/2021.2/index.html#/definitions/vendor) for available fields.
   *
   * **Example**:
   * ```
   * [
   *    {
   *      "addressBookAddress": {
   *        "addr1": "2500 Durant Ave",
   *        "addr2": "Unit A",
   *        "addrPhone": "5101112222",
   *        "addrText": "2500 Durant Ave Unit A, Berkeley, CA, 94704",
   *        "addressee": "John Appleseed",
   *        "city": "Berkeley",
   *        "state": "CA",
   *        "defaultBilling": true,
   *        "defaultShipping": true
   *      }
   *    },
   *  ]
   * ```
   */
  vendorAdditionalFields?: string;
} & (
  | {
      /**
       * Type
       *
       */
      isPerson?: undefined;
    }
  | {
      /**
       * Type
       *
       */
      isPerson: 'individual' | (string & {});

      /**
       * First Name
       *
       */
      firstName: string;

      /**
       * Last Name
       *
       */
      lastName: string;
    }
  | {
      /**
       * Type
       *
       */
      isPerson: 'company' | (string & {});
    }
);

