/**
 * Create Bill intent type
 */
type NetsuiteCreateBill = {
  /**
   * Record Type
   *
   */
  recordType?: string;

  /**
   * Vendor
   * The vendor ID this bill is associated with.
   *
   */
  entity: string;

  /**
   * Date
   * Accepts ISO 8601 date format.
   *
   * **Example**:
   * ```
   * 2022-01-31
   * ```
   */
  tranDate: string;

  /**
   * Posting Period
   * Select the period to which you want to post this transaction.
   *
   */
  postingPeriod: string;

  /**
   * Subsidiary
   * Enter the subsidiary ID to associate with this transaction. By default, the bill will use the Parent Company subsidiary.
   *
   */
  subsidiary?: string;

  /**
   * Reference Number
   * Enter additional information to identify this transaction, such as the vendor's invoice number. This reference appears on reports such as the Accounts Payable Register.
   *
   */
  tranId?: string;

  /**
   * Due Date
   * Accepts ISO 8601 date format.
   *
   * **Example**:
   * ```
   * 2022-01-31
   * ```
   */
  dueDate?: string;

  /**
   * Amount
   *
   * **Example**:
   * ```
   * 25.00
   * ```
   */
  userTotal?: string;

  /**
   * Approval Status
   *
   * **Example**:
   * ```
   * Approved
   * ```
   */
  approvalStatus?: '2' | '1' | (string & {});

  /**
   * Memo
   * Enter a memo that will appear on such reports as the 2-line Accounts Payable Register.
   *
   */
  memo?: string;

  /**
   * Expenses and Items
   * Enter an array of Expenses including the description, quantity, and amount for each Line item. See the docs (https://system.netsuite.com/help/helpcenter/en_US/APIs/REST_API_Browser/record/v1/2021.2/index.html#/definitions/vendorBill-expenseCollection) for available fields.
   *
   * **Example**:
   * ```
   * [
   *    {
   *      "account:"58",
   *      "amount": 30.99,
   *      "memo":"test"
   *    }
   *  ]
   * ```
   */
  itemsInput: string;

  /**
   * Additional Fields
   * Specify additional fields to include on this Bill as JSON. See the docs (https://system.netsuite.com/help/helpcenter/en_US/APIs/REST_API_Browser/record/v1/2021.2/index.html#/definitions/vendorBill) for available fields.
   *
   * **Example**:
   * ```
   * [
   *    {
   *      "vendorTaxItem": 10
   *    },
   *  ]
   * ```
   */
  billAdditionalFields?: string;
};

