/**
 * Create Account intent type
 */
type NetsuiteCreateAccount = {
  /**
   * Record Type
   *
   */
  recordType?: string;

  /**
   * Number
   * Enter the number to identify this account.
   *
   * **Example**:
   * ```
   * 6000
   * ```
   */
  acctNumber: string;

  /**
   * Name
   * Enter up to 31 characters for an account name that will appear on all reports.
   *
   * **Example**:
   * ```
   * Expenses
   * ```
   */
  acctName: string;

  /**
   * Subsidiaries
   * Select one or more subsidiaries by subsidiary ID to restrict the use of this account.
   *
   */
  subsidiaries: string;

  /**
   * Type
   * Select a GAAP category for the type of account you are creating.
   *
   */
  acctType:
    | 'Bank'
    | 'AcctRec'
    | 'OthCurrAsset'
    | 'FixedAsset'
    | 'OthAsset'
    | 'AcctPay'
    | 'CredCard'
    | (string & {});

  /**
   * Sub-Account Of
   * Select the parent account if this account is a sub-account of another.
   *
   */
  parent?: string;

  /**
   * Additional Fields
   * Specify additional fields to include on this Account as JSON. See the docs (https://system.netsuite.com/help/helpcenter/en_US/APIs/REST_API_Browser/record/v1/2021.2/index.html#/definitions/account) for available fields.
   *
   * **Example**:
   * ```
   * [
   *    {
   *      "availableBalance": 10
   *    }
   *  ]
   * ```
   */
  accountAdditionalFields?: string;
};

